package br.com.amcash.vehicle.service;

import br.com.amcash.user.entity.*; import br.com.amcash.vehicle.entity.*; import br.com.amcash.vehicle.repository.*;
import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;

class MaintenanceAlertServiceTests {
    @Test void shouldCreateOnlyOneAlertForTheSameMaintenance(){VehicleMaintenanceRepository maintenances=mock(VehicleMaintenanceRepository.class);MaintenanceAlertRepository alerts=mock(MaintenanceAlertRepository.class);MaintenanceAlertService service=new MaintenanceAlertService(maintenances,alerts);User user=new User("s","a@b.com","A",null);user.setId(UUID.randomUUID());Vehicle vehicle=new Vehicle(user);vehicle.update(VehicleType.CAR,"Honda","Fit",2015,2016,null,null,null,FuelType.GASOLINE,new BigDecimal("9600"),LocalDate.now(),new BigDecimal("10"),null,null,null,null);VehicleMaintenance maintenance=new VehicleMaintenance(vehicle);maintenance.update(MaintenanceType.OIL_CHANGE,null,LocalDate.now().minusMonths(3),new BigDecimal("5000"),BigDecimal.TEN,null,new BigDecimal("10000"),null);when(maintenances.findAllByVehicleIdOrderByDateDescCreatedAtDesc(vehicle.getId())).thenReturn(List.of(maintenance));AtomicReference<MaintenanceAlert> stored=new AtomicReference<>();when(alerts.findByMaintenanceId(maintenance.getId())).thenAnswer(i->Optional.ofNullable(stored.get()));when(alerts.save(any())).thenAnswer(i->{stored.set(i.getArgument(0));return i.getArgument(0);});service.reconcile(vehicle);service.reconcile(vehicle);verify(alerts,times(1)).save(any());assertEquals(MaintenanceAlertType.UPCOMING,stored.get().getType());}

    @Test void shouldMarkExceededForecastAsOverdue(){User user=new User("s","c@d.com","C",null);Vehicle vehicle=new Vehicle(user);vehicle.update(VehicleType.CAR,"A","B",2020,2020,null,null,null,FuelType.GASOLINE,new BigDecimal("11000"),LocalDate.now(),null,null,null,null,null);VehicleMaintenance maintenance=new VehicleMaintenance(vehicle);maintenance.update(MaintenanceType.BRAKES,null,LocalDate.now().minusMonths(1),new BigDecimal("9000"),BigDecimal.ZERO,null,new BigDecimal("10000"),null);assertEquals(MaintenanceAlertType.OVERDUE,MaintenanceAlertService.typeFor(maintenance,vehicle.getCurrentMileage(),LocalDate.now()));}
}
